  function clearMedia(){clearTimeout(photoRescanTimer);photoRescanTimer=0;for(const url of mediaUrls)URL.revokeObjectURL(url);mediaUrls=[];releasePhotoUrls();photoFiles=[];photoCatalogCount=0;photoWindowStart=0;photoWindowAnchors=new Map([[0,null]]);photoIndexFolderId='';photoIndexScanning=false;photoOriginalsAccessible=false;photoSourceNotice='';photoStorageWarning='';photoScanStats={added:0,modified:0,unavailable:0,checked:0};photoFolderHandle=null;photoFolderPersisted=false;photoSelectedIndex=-1;$('#mediaGrid').innerHTML='';$('#mediaGrid').scrollLeft=0;$('#mediaView').classList.remove('directory-mode');$('#mediaViewer').classList.add('hidden');$('#mediaPreview').removeAttribute('src');$('#folderGallery').classList.add('hidden');$('#folderGalleryTrack').replaceChildren();$('#folderGalleryCount').textContent='';$('#mediaFiles').value='';$('#mediaFolder').value='';$('#mediaStatus').textContent='Selecciona fotografías o una carpeta para visualizarlas.';$('#clearMediaBtn').classList.add('hidden');}
